package io.github.ningpp.compat;

/**
 * Replacement for System.Runtime.CompilerServices.StrongBox&lt;T&gt; (generated by
 * CSharpToJava converter): a reference wrapper around a value, so that code which
 * passes a value type by reference can hold on to a stable object.
 *
 * @param <T> The type of the value held by the box.
 */
public final class StrongBox<T> {

    /** C# StrongBox&lt;T&gt;.Value — the value held by the box. */
    public T value;

    /** Creates a box whose value is the default value of T. */
    public StrongBox() {
    }

    /**
     * Creates a box holding the given value.
     *
     * @param value The value to hold.
     */
    public StrongBox(T value) {
        this.value = value;
    }

    /**
     * The value held by the box, for call sites converted from the C# Value property.
     *
     * @return The value held by the box.
     */
    public T getValue() {
        return value;
    }

    /**
     * Stores a new value in the box, for call sites converted from the C# Value
     * property setter.
     *
     * @param value The value to hold.
     */
    public void setValue(T value) {
        this.value = value;
    }
}
